// Hard defaults you can change
const defaults = {
  bucket: "tools-bucket-cloudranger-30293812",
  prefix: "",  // optional path (no leading '/')
  ignoreFolders: ["processed","backups"],
  mainIndex: "security-findings",
  eventsIndex: "security-findings-events",
  processedPrefix: "processed/",             // where to move inside the same bucket
  processedBucket: "",                       // leave blank to keep same bucket

};

// Webhook sends either {body:{...}} or raw JSON
const raw = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

// normalize ignoreFolders (array or comma-separated string)
let ignore = raw.ignoreFolders;
if (typeof ignore === 'string') {
  ignore = ignore.split(',').map(s => s.trim()).filter(Boolean);
}
if (!Array.isArray(ignore)) ignore = undefined;

// normalize prefix: strip slashes, then make folderKey (trailing slash if non-empty)
const p = (raw.prefix ?? defaults.prefix ?? '').toString().replace(/^\/+|\/+$/g,'');
const folderKey = p ? (p.endsWith('/') ? p : p + '/') : '';

// final config
const cfg = {
  ...defaults,
  ...raw,
  ...(ignore ? { ignoreFolders: ignore } : {}),
  prefix: p,          // clean, no slashes
  folderKey           // S3 "Folder Key" friendly
};

return [{ json: cfg }];

const cfg = $items('Apply Defaults')?.[0]?.json || {};
const ignore = (cfg.ignoreFolders || []).map(s => String(s).replace(/\/+$/,''));
const out = [];

for (const it of $items('List Files')) {
  const key = it.json.Key || it.json.key || '';
  if (!key.toLowerCase().endsWith('.json')) continue;

  // skip ignored folders (prefix match)
  if (ignore.some(pre => pre && (key === pre || key.startsWith(pre + '/')))) continue;

  // tag tool by path/name
  let tool = 'unknown';
  if (/zaproxy|zap/i.test(key)) tool = 'zaproxy';
  else if (/checkov/i.test(key)) tool = 'checkov';
  else if (/trufflehog/i.test(key)) tool = 'trufflehog';

  out.push({
    json: {
      bucket: cfg.bucket,
      key,
      tool,
      mainIndex: cfg.mainIndex,
      eventsIndex: cfg.eventsIndex
    }
  });
}

return out;

// -------- helpers --------
function fnv1a64Hex(str){
  let h=BigInt('0xcbf29ce484222325'), p=BigInt('0x100000001b3');
  for (let i=0;i<str.length;i++){ h^=BigInt(str.charCodeAt(i)); h=(h*p)&BigInt('0xFFFFFFFFFFFFFFFF'); }
  return h.toString(16).padStart(16,'0');
}
const fingerprintOf = (tool, signature) =>
  fnv1a64Hex(JSON.stringify({ tool, signature }));

const ZAP_RISK = { "0":"Informational", "1":"Low", "2":"Medium", "3":"High" };
const ZAP_CONF = { "1":7, "2":4, "3":2, "4":1 }; // higher = more confident

const normParam = (p) => (p === '' || p == null) ? null : String(p).trim().toLowerCase();
const normMethod = (m) => {
  const v = (m || '').toString().trim().toUpperCase();
  return v || null;
};

// Parse a single ZAP scan object
function parseZap(scan){
  const sites  = Array.isArray(scan?.site) ? scan.site : [];
  const alerts = sites.flatMap(s => s?.alerts || []);
  const rows = [];

  for (const a of alerts){
    const title    = (a.alert || a.name || 'ZAP Finding').trim();
    const pluginid = String(a.pluginid || '').trim();
    const desc     = a.desc || a.description || '';
    const severity = ZAP_RISK[String(a.riskcode ?? '')] || ((a.riskdesc||'').split(' ')[0] || 'Informational');
    const conf     = ZAP_CONF[String(a.confidence ?? '')] ?? null;
    const cwe      = a.cweid || a.cwe || null;
    const siteOwner= a['Site Owner'] ?? a.site_owner ?? null;

    const inst = Array.isArray(a.instances) && a.instances.length
      ? a.instances
      : [{ uri: null, method: null, param: null }];

    for (const it of inst){
      const url    = it.uri || it.url || null;
      const method = normMethod(it.method);
      const param  = normParam(it.param);
      // NOTE: site_owner is NOT in the signature/fingerprint
      const signature = { pluginid, title, url, method, param };

      rows.push({
        tool: 'zaproxy',
        title, pluginid, severity,
        description: desc,
        scanner_confidence: conf,
        cwe,
        site_owner: siteOwner,
        url, method, param,
        signature
      });
    }
  }
  return rows;
}

// -------- main --------
const now = new Date().toISOString();
const inputItems = $input.all();
const out = [];

for (const item of inputItems) {
  const j = item.json || {};

  // These come from "Extract from file" (your sample shows them at root)
  const scan        = j.scan ?? j.data ?? j.report ?? j.content ?? j.payload ?? {};
  const tool        = j.tool        || 'zaproxy';
  const mainIndex   = j.mainIndex   || 'security-findings';
  const eventsIndex = j.eventsIndex || 'security-findings-events';

  // S3 for THIS item only
  const s3 = (j.s3 && j.s3.bucket && j.s3.key)
    ? { bucket: j.s3.bucket, key: j.s3.key }
    : (j.bucket && j.key)    // your extractor puts these at root
      ? { bucket: j.bucket, key: j.key }
      : null;

  // De-dupe only within this report
  const seen = new Set();

  const findings = parseZap(scan);
  for (const f of findings){
    const fingerprint = fingerprintOf(tool, f.signature);
    if (seen.has(fingerprint)) continue;
    seen.add(fingerprint);

    const mainDoc = {
      '@timestamp': now,
      tool,
      title: f.title,
      severity: f.severity,
      description: f.description || '',
      scanner_confidence: f.scanner_confidence ?? null,
      site_owner: f.site_owner ?? null,
      cwe: f.cwe || null,
      pluginid: f.pluginid || null,
      url: f.url ?? null,
      method: f.method ?? null,
      param: f.param ?? null,
      dedupe: { fingerprint, signature: f.signature }
    };

    const eventDoc = {
      '@timestamp': now,
      type: 'observation',
      fingerprint,
      tool,
      title: f.title,
      severity: f.severity
    };

    if (s3){ mainDoc.s3 = s3; eventDoc.s3 = s3; }

    out.push({
      json: {
        now,
        fingerprint,
        mainIndex,
        eventsIndex,
        mainDoc,
        eventDoc
      }
    });
  }
}

return out;

// Group and collapse
const groups = new Map();
for (const it of $input.all()) {
  const fp = it.json.fingerprint;
  const md = it.json.mainDoc || {};
  const ed = it.json.eventDoc || {};
  const arr = groups.get(fp) || [];
  arr.push({ md, ed });
  groups.set(fp, arr);
}

const uniq = arr => Array.from(new Set((arr||[]).filter(Boolean)));
function uniqSources(list){
  const seen = new Set(), out = [];
  for (const s of list || []) {
    if (!s || !s.bucket || !s.key) continue;
    const id = `${s.bucket}|${s.key}`;
    if (seen.has(id)) continue;
    seen.add(id);
    out.push({ bucket: s.bucket, key: s.key });
  }
  return out;
}

const out = [];
for (const [fp, arr] of groups) {
  const first = arr[0].md;
  const occurrences_delta = arr.length;
  const endpoints = uniq(arr.map(x => x.md.url));
  const sources = uniqSources(arr.map(x => x.md.s3));

  const mergedMain = { ...first, url: null, method: null, param: null };
  if (endpoints.length) mergedMain.endpoints = endpoints;

  const aggEvent = {
    '@timestamp': first['@timestamp'],
    type: 'observation',
    fingerprint: fp,
    tool: first.tool,
    title: first.title,
    severity: first.severity,
    count: occurrences_delta,
    s3: first.s3
  };

  out.push({
    json: {
      fingerprint: fp,
      now: first['@timestamp'],
      mainIndex: $json.mainIndex || 'security-findings',
      eventsIndex: $json.eventsIndex || 'security-findings-events',
      occurrences_delta,
      mainDoc: mergedMain,
      eventDoc: aggEvent,
      // 👇 union of all source objects we processed for this fingerprint
      sources
    }
  });
}
return out;

function union(a, b){ const A=Array.isArray(a)?a:[], B=Array.isArray(b)?b:[]; const s=new Set(), out=[]; for (const x of [...A,...B]) if (x!=null && !s.has(x)) { s.add(x); out.push(x); } return out; }

const prev = $items('Collapse by Fingerprint');
const got  = $input.all();

const out = [];
for (let i = 0; i < got.length; i++) {
  const esItem   = got[i].json || {};
  const baseItem = (prev[i] && prev[i].json) ? prev[i].json : {};

  const existing = esItem.Document || esItem._source || null;
  const incoming = baseItem.mainDoc || {};
  const now      = baseItem.now;
  const delta    = baseItem.occurrences_delta || 1;

  const merged = existing ? {
    ...existing,
    ...incoming,
    occurrences: (existing.occurrences || 0) + delta,
    last_seen: now,
    endpoints: union(existing.endpoints, incoming.endpoints)
  } : {
    ...incoming,
    occurrences: delta,
    last_seen: now
  };

  out.push({
    json: {
      exists: !!existing,
      index: baseItem.mainIndex,
      id: baseItem.fingerprint,
      doc: merged,
      eventsIndex: baseItem.eventsIndex,
      eventDoc: baseItem.eventDoc,
      // 👇 carry forward all files to move
      sources: baseItem.sources,
      // optional: processed config from defaults if you added them earlier
      processedPrefix: baseItem.processedPrefix,
      processedBucket: baseItem.processedBucket
    }
  });
}
return out;

function cleanPrefix(p){
  let x = (p || 'processed/').toString().trim();
  x = x.replace(/^\/+/, '');       // no leading slash
  if (!x.endsWith('/')) x += '/';  // ensure trailing slash
  return x;
}

const prefix = cleanPrefix($json.processedPrefix);
const processedBucket = $json.processedBucket || null;

// prefer the union list from Collapse → Build; fallback to single doc.s3
const srcs = Array.isArray($json.sources) ? $json.sources
           : ($json.doc?.s3 ? [ $json.doc.s3 ] : []);

return srcs
  .filter(s => s && s.bucket && s.key)
  .map(s => {
    const sourcePath = `/${s.bucket}/${s.key}`;
    const destBucket = processedBucket || s.bucket;
    const destKey = `${prefix}${s.key}`;
    const destPath = `/${destBucket}/${destKey}`;
    return { json: {
      source: s,             // { bucket, key }
      sourcePath,            // "bucket/key"
      dest: { bucket: destBucket, key: destKey },
      destPath               // "bucket/prefix/key"
    }};
  });
